// VIOC_ai_squads_resync.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
// Con persistencia, al cargar la partida el servidor restaura las mejoras (cti_upgrades) pero no vuelve a
// llamar CTI_SE_FNC_UpgradeSquads, asi que las escuadras "Auto" que compran los equipos IA
// (CTI_SQUAD_<LADO>_Infantry/Motorized/Armored/Air) se quedan solo con el nivel 0.
// Esto las reconstruye igual que si las mejoras se hubieran investigado en esta sesion.
if (!isServer) exitWith {};
{
	private _side = _x;
	private _upgrades = (_side) call CTI_CO_FNC_GetSideUpgrades;
	private _levels = missionNamespace getVariable [format ["CTI_%1_UPGRADES_LEVELS", _side], []];
	if (!isNil "_upgrades" && {_upgrades isEqualType []} && {count _levels > 0}) then {
		{
			_x params ["_upg", "_troop"];
			private _key = format ["CTI_SQUAD_%1_%2", _side, _troop];
			private _squad = missionNamespace getVariable [_key, []];
			private _cur = if (count _upgrades > _upg) then {_upgrades select _upg} else {0};
			if (count _squad > 2 && {_cur > 0} && {count _levels > _upg}) then {
				if (_cur >= (_levels select _upg)) then {
					private _all = missionNamespace getVariable [format ["%1All", _key], []];
					if (count _all > 2) then {_squad set [2, +(_all select 2)]};
				} else {
					private _pool = +(_squad select 2);
					for "_l" from 1 to _cur do {
						private _tier = missionNamespace getVariable [format ["%1T%2", _key, _l], []];
						if (count _tier > 2) then {_pool append (_tier select 2)};
					};
					_squad set [2, _pool];
				};
				missionNamespace setVariable [_key, _squad];
				diag_log format ["VIOC ai_squads_resync: %1 nivel %2 -> %3 entradas", _key, _cur, count (_squad select 2)];
			};
		} forEach [[CTI_UPGRADE_BARRACKS, "Infantry"], [CTI_UPGRADE_LIGHT, "Motorized"], [CTI_UPGRADE_HEAVY, "Armored"], [CTI_UPGRADE_AIR, "Air"]];
	};
} forEach [west, east];
